import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './supabaseClient';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import ConflictTable from './components/ConflictTable';
import GlobalResourceMonitor from './components/GlobalResourceMonitor';
import {
  LayoutDashboard, Printer, Activity, Zap, LogOut, Lock, User, RefreshCw, Globe, Calendar, List
} from 'lucide-react';

// --- PROCTOR DASHBOARD SUB-COMPONENT ---
const ProctorDashboard = ({ profile, globalSchedule, allExamDates }) => {
  const mySchedule = globalSchedule.filter(s => s.proctor === profile.full_name);

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl text-white">
        <div className="flex items-center gap-3 font-black uppercase tracking-tighter text-xl">
          <Globe size={28} className="text-blue-500" />
          ACCORD <span className="text-blue-500 italic">PROCTOR</span>
        </div>
        <div className="flex items-center gap-4">
          <div className="text-right mr-4">
            <p className="text-[10px] font-black uppercase text-slate-400">Logged in as</p>
            <p className="text-xs font-bold text-blue-400">{profile.full_name}</p>
          </div>
          <button onClick={() => supabase.auth.signOut()} className="bg-white/10 hover:bg-rose-500 text-white p-2.5 rounded-xl transition-all">
            <LogOut size={18} />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-12">
          {/* Personal Stats */}
          <div className="lg:col-span-1 bg-slate-900 rounded-[3rem] p-8 text-white shadow-2xl">
            <h2 className="text-sm font-black uppercase tracking-widest text-blue-400 mb-6 flex items-center gap-2">
              <Calendar size={16}/> My Assignments
            </h2>
            <div className="space-y-4">
              {mySchedule.length === 0 ? (
                <p className="text-slate-500 text-xs italic">No assignments found.</p>
              ) : mySchedule.map((s, i) => (
                <div key={i} className="bg-white/5 p-4 rounded-2xl border border-white/10">
                  <p className="text-[10px] font-black text-blue-400 uppercase">{s.subject_code}</p>
                  <p className="text-sm font-bold truncate">{s.subject_name}</p>
                  <div className="flex justify-between mt-2 text-[9px] font-black text-slate-400 uppercase">
                    <span>{s.exam_date}</span>
                    <span>{s.room}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Availability Log Book Placeholder */}
          <div className="lg:col-span-2 bg-white rounded-[3rem] p-8 border-2 border-slate-100 shadow-xl">
            <h2 className="text-sm font-black uppercase tracking-widest text-slate-400 mb-6 flex items-center gap-2">
              <List size={16} className="text-blue-600"/> Availability Log Book
            </h2>
            <div className="bg-slate-50 rounded-3xl p-12 text-center border-2 border-dashed border-slate-200">
               <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Self-Service Log Entries Coming Soon</p>
            </div>
          </div>
        </div>

        {/* Global Master Timeline (Read-Only) */}
        <div className="bg-white p-4 rounded-[4rem] shadow-xl border border-slate-100">
          <div className="p-8 pb-0">
             <h2 className="text-2xl font-black text-slate-900 tracking-tighter mb-4">Master <span className="text-blue-600 italic">Timeline</span></h2>
          </div>
          <ScheduleCalendar scheduleData={globalSchedule} examDates={allExamDates} readOnly={true} />
        </div>
      </main>
    </div>
  );
};

function App() {
  const [session, setSession] = useState(null);
  const [profile, setProfile] = useState(null); 
  const [loading, setLoading] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [departments, setDepartments] = useState([]);
  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [globalAvailability, setGlobalAvailability] = useState([]); // Phase 4: Availability State
  const [allExamDates, setAllExamDates] = useState([]);

  // --- AUTH & PROFILE FETCH ---
  useEffect(() => {
    const getSessionAndProfile = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session) {
        await fetchProfile(session.user.id);
        await fetchAllData();
      }
      setLoading(false);
    };

    getSessionAndProfile();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
      setSession(session);
      if (session) {
        await fetchProfile(session.user.id);
        await fetchAllData();
      } else {
        setProfile(null);
        setDepartments([]);
        setGlobalSchedule([]);
        setGlobalAvailability([]);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId) => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();

    if (!error) setProfile(data);
  };

  // --- FETCH DATA ---
  const fetchAllData = async () => {
  setLoading(true);
  try {
    // Adding a 500ms delay prevents the browser from "stealing" the DB lock 
    // if the component re-renders too fast.
    const [deptsRes, schedsRes, availRes] = await Promise.all([
      supabase.from('departments').select('*').order('name', { ascending: true }),
      supabase.from('schedules').select('*'),
      supabase.from('proctor_availability').select('*')
    ]);

    // Check for errors explicitly
    if (deptsRes.error) throw deptsRes.error;

    if (deptsRes.data) setDepartments(deptsRes.data);
    if (availRes.data) setGlobalAvailability(availRes.data);

    if (schedsRes.data) {
      const sortedData = schedsRes.data.sort((a, b) => a.id - b.id);
      const dates = [...new Set(sortedData.map(s => s.exam_date))].sort();
      setGlobalSchedule(runConflictDetection(sortedData));
      setAllExamDates(dates);
    }
  } catch (err) {
    console.error("Cloud Sync Error:", err.message);
    // Even if it fails, we MUST stop the loading spinner
  } finally {
    setLoading(false); 
  }
};

  // Conflict Counter for Nav
  const conflictCount = useMemo(() => {
    return globalSchedule.filter(s => s.hasConflict).length;
  }, [globalSchedule]);

  // --- RBAC FILTERING ---
  const visibleDepartments = useMemo(() => {
    if (!profile) return [];
    if (profile.role === 'head_admin') return departments;
    if (profile.role === 'dept_head') {
      return departments.filter(d => d.code === profile.assigned_dept);
    }
    return [];
  }, [departments, profile]);

  const handleDepartmentUpdate = async (actionType, payload) => {
    if (['manual_override', 'lock_and_save', 'schedule_sync'].includes(actionType)) {
      if (!Array.isArray(payload) || payload.length === 0) return false;

      const dataToSync = payload.map(item => {
        const { hasConflict, conflictType, ...validData } = item;
        if (validData.id && String(validData.id).includes('temp')) delete validData.id;
        if (validData.tempId) delete validData.tempId;

        return {
          ...validData,
          year_level: String(validData.year_level),
          flagged: Boolean(validData.flagged ?? false),
          isManualProctor: Boolean(validData.isManualProctor ?? false),
          original_proctor: validData.original_proctor || validData.proctor
        };
      });

      const { error } = await supabase.from('schedules').upsert(dataToSync, { onConflict: 'id' });
      if (error) { console.error(`❌ Sync Error:`, error.message); return false; }
      await fetchAllData();
      return true;
    }

    if (['proctors', 'rooms', 'subjects'].includes(actionType)) {
      if (!payload?.id) return false;
      const { error } = await supabase.from('departments').update({ [actionType]: payload[actionType] }).eq('id', payload.id);
      if (!error) setDepartments(prev => prev.map(d => d.id === payload.id ? { ...d, [actionType]: payload[actionType] } : d));
      return !error;
    }
    return true;
  };

  const handleScheduleGenerated = async (newAssignments, _newDates, deptCode) => {
    if (!newAssignments?.length) return;
    const targetYear = String(newAssignments[0].year_level);
    try {
      await supabase.from('schedules').delete().eq('dept_code', deptCode).eq('year_level', targetYear);
      const formattedData = newAssignments.map(item => ({
        dept_code: deptCode,
        year_level: String(item.year_level),
        section: item.section || 'A',
        subject_code: item.subject_code || 'N/A',
        subject_name: item.subject_name || 'N/A',
        proctor: item.proctor,
        room: item.room,
        exam_date: item.exam_date,
        start_time: item.start_time,
        end_time: item.end_time,
        flagged: false,
        flagNote: "",
        isManualProctor: false
      }));
      const { error: insertError } = await supabase.from('schedules').insert(formattedData);
      if (insertError) throw insertError;
      await fetchAllData();
    } catch (err) {
      console.error("Critical Generation Error:", err.message);
      alert("Failed to save generated schedule.");
    }
  };

  const runConflictDetection = (scheduleList) => {
    return scheduleList.map(item => {
      const conflict = scheduleList.find(target =>
        target.id !== item.id &&
        target.exam_date === item.exam_date &&
        target.section !== item.section &&
        (target.room === item.room || target.proctor === item.proctor) &&
        (item.start_time < target.end_time && item.end_time > target.start_time)
      );
      return {
        ...item,
        hasConflict: !!conflict,
        conflictType: conflict ? (conflict.room === item.room ? 'ROOM' : 'PROCTOR') : null
      };
    });
  };

  const assignDeptHead = async (userId, deptCode) => {
  const { error } = await supabase
    .from('profiles')
    .update({ 
      role: 'DEPT_ADMIN', 
      assigned_dept: deptCode 
    })
    .eq('id', userId);

  if (!error) alert("Dept Head Assigned Successfully!");
};
const createDeptAndAssignHead = async (deptName, deptCode, selectedUserId) => {
  // 1. Create the Department
  const { data: deptData, error: deptError } = await supabase
    .from('departments')
    .insert([{ name: deptName, code: deptCode.toUpperCase() }]);

  if (deptError) return alert(deptError.message);

  // 2. Automatically assign the selected user as the Dept Head
  const { error: roleError } = await supabase
    .from('profiles')
    .update({ 
      role: 'DEPT_ADMIN', 
      assigned_dept: deptCode.toUpperCase() 
    })
    .eq('id', selectedUserId);

  if (!roleError) {
    alert(`Success! ${deptCode} created and Head assigned.`);
    await fetchAllData();
  }
};

 const addDepartment = async () => {
  // 1. Prompt for the name (Minimalist approach)
  const deptName = window.prompt("Enter Department Name:");
  const deptCode = window.prompt("Enter Department Code (e.g., ICS, CAS):");

  if (!deptName || !deptCode) return;

  // 2. Insert only what the database has
  const { data, error } = await supabase
    .from('departments')
    .insert([{ 
      name: deptName, 
      code: deptCode.toUpperCase() 
    }]);

  if (error) {
    console.error(error);
    alert(`Error: ${error.message}`);
  } else {
    alert("Department Created! Now assign a Dept Head.");
    await fetchAllData();
  }
};

  const deleteDepartment = async (deptId, deptCode) => {
    if (window.confirm(`Delete ${deptCode} permanently?`)) {
      await supabase.from('departments').delete().eq('id', deptId);
      setDepartments(prev => prev.filter(d => d.id !== deptId));
      setGlobalSchedule(prev => prev.filter(item => item.dept_code !== deptCode));
    }
  };

  const handleSignIn = async () => {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) alert(error.message);
  };

  const handleSignUp = async () => {
  setLoading(true); // Start the spinner
  try {
    // 1. Standard Supabase Auth Signup
    const { data, error } = await supabase.auth.signUp({ 
      email, 
      password,
      options: {
        data: { full_name: fullName || 'New User' }
      }
    });

    if (error) throw error;

    if (data?.user) {
      // 2. THE CATCH: Check if any Head Admin exists in the profiles table
      const { count, error: countError } = await supabase
        .from('profiles')
        .select('*', { count: 'exact', head: true })
        .eq('role', 'HEAD_ADMIN');

      if (countError) throw countError;

      // 3. If count is 0, this is the very first admin. Auto-promote them.
      if (count === 0) {
        const { error: updateError } = await supabase
          .from('profiles')
          .update({ 
            role: 'HEAD_ADMIN',
            full_name: fullName 
          })
          .eq('id', data.user.id);

        if (updateError) throw updateError;

        alert("First account detected: You have been promoted to Head Admin!");
        window.location.reload(); 
      } else {
        alert("Registration successful! Please check your email for confirmation.");
      }
    }
  } catch (err) {
    console.error("Signup Error:", err.message);
    alert(err.message);
  } finally {
    setLoading(false); // Stop the spinner even if it fails
  }
};

  if (!session) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6">
        <div className="bg-white w-full max-w-md rounded-[3.5rem] p-12 shadow-2xl">
          <div className="text-center mb-10">
            <div className="inline-flex bg-blue-600 p-5 rounded-[2rem] mb-6 text-white shadow-xl">
              <Lock size={32} />
            </div>
            <h1 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900">Accord <span className="text-blue-600">Pro</span></h1>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Institutional Workspace</p>
          </div>
          <div className="space-y-4">
            <div className="relative">
              <User className="absolute left-5 top-5 text-slate-300" size={18} />
              <input type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-slate-50 p-5 pl-14 rounded-2xl font-black text-xs border-2 border-slate-50 outline-none focus:border-blue-500" />
            </div>
            <div className="relative">
              <Lock className="absolute left-5 top-5 text-slate-300" size={18} />
              <input type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-slate-50 p-5 pl-14 rounded-2xl font-black text-xs border-2 border-slate-50 outline-none focus:border-blue-500" />
            </div>
            <button onClick={handleSignIn} className="w-full bg-slate-900 text-white p-5 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95">Sign In</button>
            <button onClick={handleSignUp} className="w-full text-slate-400 p-2 font-black uppercase text-[9px] hover:text-blue-600">Register</button>
          </div>
        </div>
      </div>
    );
  }

 // --- PROCTOR REDIRECT ---
  if (profile?.role === 'proctor') {
    return (
      <ProctorDashboard 
        profile={profile} 
        globalSchedule={globalSchedule} 
        allExamDates={allExamDates}
        onUpdateAvailability={(entry) => console.log("Syncing to DB:", entry)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl text-white">
        <div className="flex items-center gap-3 font-black uppercase tracking-tighter text-xl">
          <LayoutDashboard size={28} className="text-blue-500" />
          ACCORD <span className="text-blue-500 italic">PRO</span>
        </div>
        <div className="flex items-center gap-6">
          <div className={`px-5 py-2 rounded-2xl border-2 flex items-center gap-2 text-[10px] font-black uppercase transition-all ${conflictCount > 0 ? 'bg-rose-500/10 border-rose-500/50 text-rose-500' : 'bg-emerald-500/10 border-emerald-500/50 text-emerald-500'}`}>
            <Activity size={14} className={conflictCount > 0 ? 'animate-pulse' : ''} />
            {conflictCount > 0 ? `${conflictCount} Conflicts` : 'Sync Active'}
          </div>

          {/* EXCLUSIVE: Only Head Admin can add departments */}
          {profile?.role === 'HEAD_ADMIN' && (
            <button onClick={addDepartment} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-2xl font-black text-[10px] uppercase shadow-lg transition-all active:scale-95">Add Dept</button>
          )}

          <button onClick={() => supabase.auth.signOut()} className="bg-white/10 hover:bg-rose-500 text-white p-2.5 rounded-xl transition-all">
            <LogOut size={18} />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-40">
            <RefreshCw size={48} className="text-blue-500 animate-spin mb-4" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Syncing Cloud Database...</p>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 gap-12 mb-16">
              <ConflictTable schedule={globalSchedule} />
              <GlobalResourceMonitor allDepartments={departments} globalSchedule={globalSchedule} />
            </div>

            <div className="space-y-16">
              {visibleDepartments.map((dept) => (
                <DepartmentCard
                  key={dept.id}
                  dept={dept}
                  role={profile?.role} 
                  allDepartments={departments}
                  onUpdate={handleDepartmentUpdate}
                  onDeleteDept={deleteDepartment}
                  globalAvailability={globalAvailability} // Phase 4 Prop
                  onClearSchedule={async (dCode, yLevel) => {
                    if (window.confirm(`Delete all Year ${yLevel} schedules for ${dCode}?`)) {
                      const { error } = await supabase.from('schedules').delete().eq('dept_code', dCode).eq('year_level', String(yLevel));
                      if (!error) await fetchAllData();
                    }
                  }}
                  globalSchedule={globalSchedule}
                  onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
                />
              ))}
            </div>

            <div className="mt-32 pt-24 border-t-4 border-slate-900/5 text-center">
              <div className="flex justify-between items-end mb-12 px-6">
                <h2 className="text-6xl font-black text-slate-900 tracking-tighter">Master <span className="text-blue-600 italic">Timeline</span></h2>
                <button onClick={() => window.print()} className="bg-slate-900 text-white px-10 py-5 rounded-[2.5rem] font-black text-[10px] uppercase tracking-widest flex items-center gap-3 shadow-2xl active:scale-95 transition-all">
                  <Printer size={20} /> Export Master PDF
                </button>
              </div>
              <div className="bg-white p-4 rounded-[4rem] shadow-xl border border-slate-100 text-left">
                {globalSchedule.length > 0 ? (
                  <ScheduleCalendar scheduleData={globalSchedule} examDates={allExamDates} />
                ) : (
                  <div className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.5em] text-sm">
                    <Zap size={48} className="mx-auto mb-4 opacity-20" /> Database Empty
                  </div>
                )}
              </div>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export default App;
